WITH "r0" AS ( SELECT "s".* FROM "public"."mutation_item" AS "s" WHERE true AND ( ( true AND ( "s"."id" = $1 ) ) ) ) SELECT (SELECT row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "t0"."title" AS "title" , "c2"."j" AS "owner" ) AS "%")) FROM "r0" AS "t0" LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT "t1"."name" AS "name" ) AS "%")) AS "j" FROM ( SELECT "s".* FROM "public"."mutation_author" AS "s" WHERE true AND "s"."id" = "t0"."owner_id" AND ( ( true ) ) LIMIT 1 ) AS "t1" ) AS "c2" ON true )
WITH "r0" AS ( SELECT "s".* FROM "public"."mutation_item" AS "s" WHERE true AND ( ( true AND ( "s"."id" = $1 ) ) ) ) SELECT (SELECT row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" ) AS "%")) FROM "r0" AS "t0" )
